 const i=S.findIndex(s=>s.id===id),s=S[i];seen.add(id);
 let h=s.h.replace(/<table/g,'<div class="sc"><table').replace(/<\/table>/g,'</table></div>').replace(/<div class="sc"><div class="sc">/g,'<div class="sc">').replace(/<\/table><\/div><\/div>/g,'</table></div>');
 const p=S[i-1],n=S[i+1];
 h+='<div class="pn"><span>'+(p?'<button class="btn" data-g="'+p.id+'">Back</button>':'')+'</span><span>'+(n?'<button class="btn" data-g="'+n.id+'">Next: '+n.t+'</button>':'')+'</span></div>';
 main.innerHTML=h;
 main.querySelectorAll('[data-g]').forEach(b=>b.onclick=()=>show(b.dataset.g));
 nav.querySelectorAll('button').forEach(b=>{b.classList.toggle('on',b.dataset.id===id);b.classList.toggle('seen',seen.has(b.dataset.id)&&b.dataset.id!==id)});
 if(id==='ip')initIp();if(id==='quiz')initQuiz();if(id==='games')initGames();if(id==='tools')initTools();if(id==='vault')initVault();if(id==='admin')initAdmin();if(id==='phish')initPhish();if(id==='lab')initLab();if(id==='code')initCode();if(id==='premium')initPremium();if(id==='start')initStart();
 window.scrollTo(0,0);
